service.method:

	SELECT
     	USER_ID AS EMPCD,
		'COOPERATION' AS APPTYPE
	FROM
		SUSMT
	WHERE
		HOUSE_CODE = ${session.HOUSE_CODE}
		AND COMPANY_CODE = ${session.COMPANY_CODE}
		AND USER_ID = (
			SELECT 
				CTRL_PERSON_ID 
			FROM SBALN 
			WHERE CTRL_CODE ='APP_COOPERATOR' 
			  AND HOUSE_CODE = ${session.HOUSE_CODE}
			  AND COMPANY_CODE = ${session.COMPANY_CODE}
		) 
	UNION ALL
	SELECT 
		MANAGER_POSITION AS EMPCD,
		'APPROVAL' AS APPTYPE
	  FROM SUSMT
	 WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	   AND COMPANY_CODE = ${session.COMPANY_CODE}
	   AND USER_ID = ${session.ID}


SELECT
	  SUBJECT 						AS SUBJECT
	, SUBMISSION_PLACE 				AS SUBMISSION_PLACE
	, EXPLANATION 					AS EXPLANATION
FROM SSIAD  
WHERE HOUSE_CODE 	= ${session.HOUSE_CODE}
AND COMPANY_CODE 	= ${session.COMPANY_CODE}
AND SMR_NUMBER 	= ${SMR_NUMBER}
ORDER BY SMR_NUMBER DESC


UPDATE SGWGL
   SET SUX_WKEY4 = ${IAMS_DOC_NO}
 WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
   AND COMPANY_CODE 	= ${session.COMPANY_CODE}
   AND APP_NO = ${APP_NO}
   AND APP_NO_SEQ = ${APP_NO_SEQ}


UPDATE SSIAD
   SET APPR_DOC_NO = ${APPR_DOC_NO}
 WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND SMR_NUMBER 	= ${SMR_NUMBER}


UPDATE SSETL
   SET APVID = ${APVID}
 WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND SMR_NUMBER 	= ${SMR_NUMBER}


	SELECT 
		ATTACH_NO
	FROM SSEDC 
	WHERE HOUSE_CODE = ${session.HOUSE_CODE}
      AND COMPANY_CODE = ${session.COMPANY_CODE}
      AND SMR_NUMBER = ${SMR_NUMBER}


	SELECT 
		OTHER_FILE_NO
	FROM SSIPD
	WHERE HOUSE_CODE = ${session.HOUSE_CODE}
      AND COMPANY_CODE = ${session.COMPANY_CODE}
      AND SMR_NUMBER = ${SMR_NUMBER}
